<?php declare(strict_types=1);
namespace Interferencia\Modules\Finance;
use PDO;
final readonly class CampaignRepository{public function __construct(private PDO$database){}public function all():array{return$this->database->query('SELECT c.*,u.name created_by_name FROM finance_campaigns c INNER JOIN users u ON u.id=c.created_by ORDER BY c.is_active DESC,c.valid_until DESC,c.name')->fetchAll();}public function active():array{return$this->database->query('SELECT * FROM finance_campaigns WHERE is_active=1 AND valid_until>=CURRENT_DATE ORDER BY valid_until,name')->fetchAll();}public function find(int$id):?array{$s=$this->database->prepare('SELECT * FROM finance_campaigns WHERE id=:id');$s->execute(['id'=>$id]);$row=$s->fetch();return is_array($row)?$row:null;}public function save(?int$id,string$name,float$discount,string$validUntil,bool$active,int$userId):int{if($id===null){$s=$this->database->prepare('INSERT INTO finance_campaigns(name,discount_percent,valid_until,is_active,created_by) VALUES(:name,:discount,:valid,:active,:user)');$s->execute(['name'=>$name,'discount'=>$discount,'valid'=>$validUntil,'active'=>(int)$active,'user'=>$userId]);return(int)$this->database->lastInsertId();}$s=$this->database->prepare('UPDATE finance_campaigns SET name=:name,discount_percent=:discount,valid_until=:valid,is_active=:active WHERE id=:id');$s->execute(['name'=>$name,'discount'=>$discount,'valid'=>$validUntil,'active'=>(int)$active,'id'=>$id]);return$id;}}
